import { tags } from "typia";

/**
 * Aggregated review statistics for a product, including average rating, total review count, and rating distribution across all 5 star levels. Displayed on product listings and detail pages to help customers evaluate product quality at a glance.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallReviewStatistic = {
  /**
   * Average star rating from all customer reviews for this product. Value is null when the product has no reviews. Range: 1.00 to 5.00, rounded to 2 decimal places.
   *
   * @x-autobe-specification Computed value: SELECT AVG(rating) FROM shopping_mall_reviews WHERE product_id = ? AND deleted_at IS NULL. Round result to 2 decimal places using ROUND(avg, 2). Return NULL when no reviews exist for the product. Valid range: 1.00 to 5.00.
   */
  averageRating: (number & tags.Minimum<1> & tags.Maximum<5>) | null;

  /**
   * Total number of customer reviews written for this product. Only includes active (non-deleted) reviews.
   *
   * @x-autobe-specification Computed value: SELECT COUNT(*) FROM shopping_mall_reviews WHERE product_id = ? AND deleted_at IS NULL. Returns 0 when no reviews exist. Only counts non-deleted reviews.
   */
  totalReviewCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Breakdown of review counts by star rating level (1 through 5 stars). Shows how many customers gave each rating, enabling quick assessment of rating distribution.
   *
   * @x-autobe-specification Computed value: SELECT rating, COUNT(*) FROM shopping_mall_reviews WHERE product_id = ? AND deleted_at IS NULL GROUP BY rating. Transform into object with keys '1' through '5'. Ensure all 5 rating levels are present in the response object - use 0 for any rating level that has no reviews. Example: { '1': 0, '2': 2, '3': 5, '4': 10, '5': 25 }
   */
  ratingDistribution: {
    /**
     * Count of 1-star reviews
     */
    "1": number & tags.Type<"int32"> & tags.Minimum<0>;

    /**
     * Count of 2-star reviews
     */
    "2": number & tags.Type<"int32"> & tags.Minimum<0>;

    /**
     * Count of 3-star reviews
     */
    "3": number & tags.Type<"int32"> & tags.Minimum<0>;

    /**
     * Count of 4-star reviews
     */
    "4": number & tags.Type<"int32"> & tags.Minimum<0>;

    /**
     * Count of 5-star reviews
     */
    "5": number & tags.Type<"int32"> & tags.Minimum<0>;
  };
};
